        private string BuildEmployeeQuery(bool isHO, bool isGroup4)
        {
            string extraCondition = "";

            if (!isHO)
            {
                extraCondition = " AND C.LOCPLACE <> 1544713937669 ";
            }

            // GROUP4 condition (if any special logic needed)
            if (isGroup4)
            {
                // add extra filters here if needed
            }           

            string query = @$"SELECT aa.HREMPLOYMASTID, AA.IDCARD, B.OIDNO as MIDCARD, C.FNAME,'{Class.Users.HCompcode}' COMPCODE, aa.PAYPERIOD, aa.BRANCH, aa.BANDid, aa.GENDER, aa.TYPENAME  FROM ( SELECT aa.*,DENSE_RANK() OVER (PARTITION BY AA.GENDER,AA.BRANCH,AA.BANDID ORDER BY AA.EMPNAME) SNO   FROM (     SELECT C.HREMPLOYMASTID, A.BRANCH, D.BANDID, C.GENDER,TO_NUMBER(B.IDCARD) IDCARD, C.FNAME EMPNAME,G.DESIGNATION MACHINENAME, F.SNO1 AS PAYPERIOD,'{combotypename.Text}' TYPENAME  FROM OTSTAMENT  A     JOIN HREMPLOYDETAILS B ON A.EMPID = B.IDCARD JOIN HREMPLOYMAST C ON B.HREMPLOYMASTID = C.HREMPLOYMASTID   JOIN HRBANDMAST D ON B.BAND = D.HRBANDMASTID JOIN MACHINEMAST E ON E.MACHINEMASTID = B.MACNAME   JOIN WEEKLYPAYFRQ F ON A.WEEKCODE = F.PAYPERIOD AND A.FROMDATE = F.STDT JOIN HRDESIGNATIONMAST G ON G.HRDESIGNATIONMASTID = B.DESIGNATION  JOIN GTCOMPMAST H ON H.GTCOMPMASTID = C.COMPCODE   WHERE F.SNO1 = '{combopayperiod.Text}'  AND (A.BRANCH = '{combobranch.Text}' OR '{combobranch.Text}' = 'ALL')    AND (D.BANDID = '{comboband.Text}' OR '{comboband.Text}' = 'ALL')  AND (C.GENDER = '{combogender.Text}' OR '{combogender.Text}' = 'ALL')  " + extraCondition + @" ) aa   ) AA JOIN HREMPLOYDETAILS B ON AA.IDCARD = B.IDCARD JOIN HREMPLOYMAST C ON C.HREMPLOYMASTID = B.HREMPLOYMASTID ORDER BY AA.IDCARD";
            return query;
        }
        public void GridLoad()
        {
            i = 1;
            if (combopayperiod.Text != "")
            {
                string sel1 = "";
                listView2.Items.Clear(); listfilter2.Items.Clear(); allip.Items.Clear();
                bool isHO = Class.Users.HUserName == "HO";
                bool isGroup4 = Class.Users.HUserName == "GROUP4";
                string query = BuildEmployeeQuery(isHO, isGroup4);     
                DataSet ds1 = Utility.ExecuteSelectQuery(query, "HREMPLOYMAST");
                DataTable dt1 = ds1.Tables["HREMPLOYMAST"];
               
                if (dt1.Rows.Count > 0)
                {
                    listView2.BeginUpdate();
                    foreach (DataRow myRow in dt1.Rows)
                    {
                        ListViewItem list = new ListViewItem();


                        list.SubItems.Add(i.ToString());
                        list.SubItems.Add(myRow["HREMPLOYMASTID"].ToString());
                        list.SubItems.Add(myRow["IDCARD"].ToString());
                        list.SubItems.Add(myRow["MIDCARD"].ToString());
                        list.SubItems.Add(myRow["FNAME"].ToString());
                        list.SubItems.Add(myRow["COMPCODE"].ToString());
                        list.SubItems.Add(myRow["PAYPERIOD"].ToString());
                        list.BackColor = (i % 2 == 0) ? Color.White : Color.WhiteSmoke;
                        this.listfilter2.Items.Add((ListViewItem)list.Clone());
                        listView2.Items.Add(list); lbllistviewcount.Refresh();
                        lbllistviewcount.Text = "Total Count    : " + listView2.Items.Count;
                        i++;
                    }
                    listView2.EndUpdate();
                }
                else
                {
                    mas.pop("No Data Found", "","");
                }
            }
            else
            {
                mas.pop("Pls Select Mandatory Fields","","");
            }
        }
