        private DataTable GetPayroll_OT1(string empId, string paypreiod)
        {

            string sel2 = "SELECT A.FROMDATE||' - '||A.TODATE AS  PERIOD,A.BUYER OTMIN,ROUND(((((BASIC+DA+SPL)/26)/8)/60)*2*A.BUYER,2) OTAMT,  CASE WHEN B.ESI = 'YES' THEN ROUND(ROUND(((((BASIC+DA+SPL)/26)/8)/60)*2*A.BUYER,2)*0.75/100,2) ELSE 0 END ESI,  ROUND(((((BASIC+DA+SPL)/26)/8)/60)*2*A.BUYER,2) - CASE WHEN B.ESI = 'YES' THEN ROUND(ROUND(((((BASIC+DA+SPL)/26)/8)/60)*2*A.BUYER,2)*0.75/100,2) ELSE 0 END NETAMOUNT FROM OTSTAMENT A JOIN HREMPLOYDETAILS B ON A.EMPMAID = B.HREMPLOYMASTID JOIN WEEKLYPAYFRQ C ON C.STDT = A.FROMDATE  WHERE B.IDACTIVE = 'YES'  AND  C.SNO1 ='" + paypreiod + "' AND B.IDCARD= '" + empId + "' AND A.BUYER > 0  ORDER BY A.FROMDATE";
            DataSet ds2 = Utility.ExecuteSelectQuery(sel2, "ASPTBLEMP");

            return ds2.Tables["ASPTBLEMP"];
        }
        private DataTable GetPayroll_OT(string empId, string payPeriod)
        {
           string query = @$"SELECT AA.EMPID,AA.FNAME,AA.DOCDATE, CASE WHEN AA.COMTEMP IS NULL AND AA.SHIFTCNT = 0 THEN 'Absent' ELSE AA.COMTEMP END COMTEMP,CASE WHEN AA.STEMP IS NULL AND AA.SHIFTCNT = 0 THEN 'Absent' ELSE AA.STEMP END STEMP ,CASE WHEN AA.SHIFTCNT = 0 AND(AA.OD > 0 OR AA.EL > 0) THEN DECODE(AA.OD,1,0,AA.OD)+DECODE(AA.EL, 1, 0, AA.EL) ELSE CASE WHEN AA.SHIFTCNT < 1 THEN AA.SHIFTCNT + DECODE(AA.OD, 1, 0, AA.OD) + DECODE(AA.EL, 1, 0, AA.EL) ELSE AA.SHIFTCNT END END SHIFTCNT  , AA.OT / 60 OT,CASE WHEN AA.INDT1 IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(AA.INDT1,'DD/MM/YYYY HH24:MI:SS'),'HH24:MI:SS') ELSE '' END INTIME,CASE WHEN AA.OUTDT1 IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(AA.OUTDT1,'DD/MM/YYYY HH24:MI:SS'),'HH24:MI:SS') ELSE '' END OUTTIME, CASE WHEN AA.INDT1 IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(AA.INDT1,'DD/MM/YYYY HH24:MI:SS'),'DD/MM/YYYY') ELSE '' END INDATE,  CASE WHEN AA.OUTDT1 IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(AA.OUTDT1,'DD/MM/YYYY HH24:MI:SS'),'DD/MM/YYYY') ELSE '' END OUTDATE,TO_CHAR(AA.DOCDATE, 'Day') DOCDAY FROM(SELECT AA.EMPID, AA.FNAME, AA.DOCDATE, AA.COMTEMP, AA.STEMP, AA.SHIFTCNT, AA.OT, AA.IDCARD, AA.INDT1, AA.OUTDT1,  NVL((    SELECT SUM(A.OLHDCNT)  SHIFTCNT FROM HRONDUTYDET  A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID  AND B.HREMPLOYMASTID = D.HREMPLOYMASTID AND A.ODATE = AA.DOCDATE  AND E.BRANCHNAME = AA.BRANCH AND D.IDCARD = AA.EMPID ), 0) OD, NVL((SELECT(0 - SUM(A.STKOPBAL)) SHIFTCNT FROM HRLEAVEREGMAST A  WHERE A.LEAVETYPE = 'EL' AND A.LTYPE <> 'ENC'  AND A.LRDATE = AA.DOCDATE AND A.IDNOCHK = AA.IDCARD  GROUP BY A.IDNOCHK, A.LRDATE),0) EL,NVL((SELECT AA.LHDCNT     FROM HRLEAVEREQMAST A, HRLEAVEREQDETAIL  AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.HRLEAVEREQMASTID = AA.HRLEAVEREQMASTID AND A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID AND A.LTYPE = 'ML' AND AA.LDATE = AA.DOCDATE AND  E.BRANCHNAME = AA.BRANCH AND D.IDCARD = AA.EMPID AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ),0) ML FROM( SELECT A.EMPID, B.FNAME, A.DOCDATE, '' COMTEMP, '' STEMP, A.SHIFTCNT, A.OT, A.EMPID IDCARD, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM LOGINLOGOUTREPORT A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, GTCOMPMAST F, HRBANDMAST G WHERE A.EMPID = D.IDCARD AND D.BAND = G.HRBANDMASTID AND D.IDCARD = '{empId}' AND A.DOCDATE BETWEEN (SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE(A.SNO1 ='{payPeriod}')) AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE(A.SNO1 = '{payPeriod}')) AND B.HREMPLOYMASTID = D.HREMPLOYMASTID AND E.BRANCHMASTID = B.WORKNATURE AND B.COMPCODE = F.GTCOMPMASTID AND NOT EXISTS(SELECT 'X' FROM( SELECT A.EMPID, B.FNAME, A.DOCDATE, A.TEMPLATE COMTEMP, A.TEMPL STEMP, A.SHIFTCNT, A.OT, A.EMPID IDCARD, CASE WHEN A.INTIME IS NOT NULL AND A.INDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.INDT || ' ' || A.INTIME, 'DD/MM/YY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END INDT1, CASE WHEN A.OUTTIME IS NOT NULL AND A.OUTDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.OUTDT || ' ' || A.OUTTIME, 'DD/MM/YY HH24:MI:SS') + NUMTODSINTERVAL(A.OT, 'MINUTE'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END OUTDT1,B.HREMPLOYMASTID FROM BHDATTA A, HREMPLOYMAST B, HREMPLOYDETAILS D WHERE A.EMPMAID = B.HREMPLOYMASTID AND D.IDCARD = '{empId}' AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.ODATE DOCDATE, 'On Duty' COMTEMP, 'On Duty' STEMP, CASE WHEN A.OHDAY = 'I & II' THEN 1 ELSE 0 END SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.ODATE, 'DD/MM/YYYY') INDT1, TO_CHAR(A.ODATE, 'DD/MM/YYYY') OUTDT1, B.HREMPLOYMASTID FROM HRONDUTYDET  A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID AND A.OHDAY = 'I & II' AND A.ODATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(E.BRANCHNAME = '{combobranch.Text}' OR 'ALL' = '{combobranch.Text}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.DOCDATE, 'Leave' COMTEMP, 'Leave' STEMP, A.SHIFTCNT,0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') INDT1, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') OUTDT1, B.HREMPLOYMASTID FROM(SELECT A.IDCARD, A.IDNOCHK, A.LRDATE DOCDATE, (0 - SUM(A.STKOPBAL)) SHIFTCNT FROM HRLEAVEREGMAST A WHERE A.LRDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') GROUP BY A.IDCARD, A.IDNOCHK, A.LRDATE HAVING(0 - SUM(A.STKOPBAL)) = 1) A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = B.HREMPLOYMASTID AND B.WORKNATURE = E.BRANCHMASTID AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT DISTINCT A.EMPID, A.FNAME, A.DOCDATE, A.COMTEMP, A.STEMP, A.SHIFTCNT,     A.OT, A.IDCARD, A.INDT1, A.OUTDT1, A.HREMPLOYMASTID     FROM( SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.NHDATE DOCDATE, A.HOLCAT COMTEMP, A.HOLCAT STEMP, 1 SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM HRNHDYDETAIL  A, HRNHDYBRANCHDET AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, BHDATTA F, HRBANDMAST G WHERE A.HRNHDYDETAILID = AA.HRNHDYDETAILID AND B.WORKNATURE = E.BRANCHMASTID  AND D.BAND = G.HRBANDMASTID AND AA.BRANCHNAME = E