ATURE = E.BRANCHMASTID AND A.LTYPE = 'ML' AND AA.LHDCNT = 1  AND D.IDCARD = '{empId}' AND AA.LDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ) AA ) AA JOIN HREMPLOYDETAILS BB ON BB.IDCARD = AA.EMPID JOIN HREMPLOYMAST DD ON BB.HREMPLOYMASTID = DD.HREMPLOYMASTID JOIN GTLOCMAST CC ON CC.GTLOCMASTID = DD.LOCPLACE WHERE AA.EMPID = '{empId}' AND NOT EXISTS(SELECT* FROM ( SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B, GTLOCMAST C, GTDEPTDESGMAST D  WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND B.LOCPLACE = C.GTLOCMASTID  AND A.DEPTNAME = D.GTDEPTDESGMASTID AND (D.DISPNAME IN ('CANTEEN','SECURITY','DRIVER')  OR C.LOCNAME = 'HEAD OFFICE' ) UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND B.EMPTYPE = 'Trainee' UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND A.LASTWORKDAY <= (SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND A.DOJ > (SELECT MAX(A.ENDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}')  ) ZZ WHERE ZZ.IDCARD = AA.IDCARD ) ORDER BY 1,3";
