 WHERE AAA.HRSHIFTTEMPID = ABB.HRSHIFTTEMPID AND ABB.TEMP = B.TEMP AND ABB.SHIFT = B.SHIFT AND B.STEMPLATE = ABB.STEMPLATE AND ABB.APPLIEDON <= TO_DATE(AA.DOCDATE) AND UPPER(AAA.CAT) = UPPER('BUYER')) AND B.APPLIEDON <= TO_DATE(AA.DOCDATE) AND C.TEMPNAME = AA.STEMP ) ET,TO_CHAR(AA.DOCDATE, 'Day') DOCDAY FROM(SELECT AA.EMPID, AA.FNAME, AA.DOCDATE, AA.COMTEMP, AA.STEMP, AA.SHIFTCNT, AA.OT, AA.IDCARD, AA.INDT1, AA.OUTDT1,  NVL((    SELECT SUM(A.OLHDCNT)  SHIFTCNT FROM HRONDUTYDET  A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID  AND B.HREMPLOYMASTID = D.HREMPLOYMASTID AND A.ODATE = AA.DOCDATE  AND E.BRANCHNAME = AA.BRANCH AND D.IDCARD = AA.EMPID ), 0) OD, NVL((SELECT(0 - SUM(A.STKOPBAL)) SHIFTCNT FROM HRLEAVEREGMAST A  WHERE A.LEAVETYPE = 'EL' AND A.LTYPE <> 'ENC'  AND A.LRDATE = AA.DOCDATE AND A.IDNOCHK = AA.IDCARD  GROUP BY A.IDNOCHK, A.LRDATE),0) EL,NVL((SELECT AA.LHDCNT     FROM HRLEAVEREQMAST A, HRLEAVEREQDETAIL  AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.HRLEAVEREQMASTID = AA.HRLEAVEREQMASTID AND A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID AND A.LTYPE = 'ML' AND AA.LDATE = AA.DOCDATE AND  E.BRANCHNAME = AA.BRANCH AND D.IDCARD = AA.EMPID AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ),0) ML FROM( SELECT A.EMPID, B.FNAME, A.DOCDATE, '' COMTEMP, '' STEMP, A.SHIFTCNT, A.OT, A.EMPID IDCARD, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM LOGINLOGOUTREPORT A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, GTCOMPMAST F, HRBANDMAST G WHERE A.EMPID = D.IDCARD AND D.BAND = G.HRBANDMASTID AND D.IDCARD = '{empId}' AND A.DOCDATE BETWEEN (SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE(A.SNO1 ='{payPeriod}')) AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE(A.SNO1 = '{payPeriod}')) AND B.HREMPLOYMASTID = D.HREMPLOYMASTID AND E.BRANCHMASTID = B.WORKNATURE AND B.COMPCODE = F.GTCOMPMASTID AND NOT EXISTS(SELECT 'X' FROM( SELECT A.EMPID, B.FNAME, A.DOCDATE, A.TEMPLATE COMTEMP, A.TEMPL STEMP, A.SHIFTCNT, A.OT, A.EMPID IDCARD, CASE WHEN A.INTIME IS NOT NULL AND A.INDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.INDT || ' ' || A.INTIME, 'DD/MM/YY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END INDT1, CASE WHEN A.OUTTIME IS NOT NULL AND A.OUTDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.OUTDT || ' ' || A.OUTTIME, 'DD/MM/YY HH24:MI:SS') + NUMTODSINTERVAL(A.OT, 'MINUTE'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END OUTDT1,B.HREMPLOYMASTID FROM BHDATTA A, HREMPLOYMAST B, HREMPLOYDETAILS D WHERE A.EMPMAID = B.HREMPLOYMASTID AND D.IDCARD = '{empId}' AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.ODATE DOCDATE, 'On Duty' COMTEMP, 'On Duty' STEMP, CASE WHEN A.OHDAY = 'I & II' THEN 1 ELSE 0 END SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.ODATE, 'DD/MM/YYYY') INDT1, TO_CHAR(A.ODATE, 'DD/MM/YYYY') OUTDT1, B.HREMPLOYMASTID FROM HRONDUTYDET  A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID AND A.OHDAY = 'I & II' AND A.ODATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(E.BRANCHNAME = '{combobranch.Text}' OR 'ALL' = '{combobranch.Text}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.DOCDATE, 'Leave' COMTEMP, 'Leave' STEMP, A.SHIFTCNT,0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') INDT1, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') OUTDT1, B.HREMPLOYMASTID FROM(SELECT A.IDCARD, A.IDNOCHK, A.LRDATE DOCDATE, (0 - SUM(A.STKOPBAL)) SHIFTCNT FROM HRLEAVEREGMAST A WHERE A.LRDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') GROUP BY A.IDCARD, A.IDNOCHK, A.LRDATE HAVING(0 - SUM(A.STKOPBAL)) = 1) A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E WHERE A.IDCARD = B.HREMPLOYMASTID AND B.WORKNATURE = E.BRANCHMASTID AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT DISTINCT A.EMPID, A.FNAME, A.DOCDATE, A.COMTEMP, A.STEMP, A.SHIFTCNT,     A.OT, A.IDCARD, A.INDT1, A.OUTDT1, A.HREMPLOYMASTID     FROM( SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.NHDATE DOCDATE, A.HOLCAT COMTEMP, A.HOLCAT STEMP, 1 SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM HRNHDYDETAIL  A, HRNHDYBRANCHDET AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, BHDATTA F, HRBANDMAST G WHERE A.HRNHDYDETAILID = AA.HRNHDYDETAILID AND B.WORKNATURE = E.BRANCHMASTID  AND D.BAND = G.HRBANDMASTID AND AA.BRANCHNAME = E.BRANCHNAME AND D.IDCARD = '{empId}' AND F.EMPID = D.IDCARD AND F.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND A.NHDATE >= D.DOJ AND(A.NHDATE < D.LASTWORKDAY OR D.LASTWORKDAY IS NULL) AND A.NHDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ) A UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, AA.LDATE DOCDATE, 'ML' COMTEMP, 'ML' STEMP, 0 SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(AA.LDATE, 'DD/MM/YYYY') INDT1, TO_CHAR(AA.LDATE, 'DD/MM/YYYY') OUTDT1, B.HREMPLOYMASTID FROM HRLEAVEREQMAST A, HRLEAVEREQDETAIL  AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, HRBANDMAST G WHERE A.HRLEAVEREQMASTID = AA.HRLEAVEREQMASTID AND A.IDCARD = D.HREMPLOYDETAILSID AND D.BAND = G.HRBANDMASTID AND B.WORKNATURE = E.BRANCHMASTID AND A.LTYPE = 'ML' AND D.IDCARD = '{empId}' AND AA.LDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID AND AA.LHDCNT = 1 ) X WHERE X.EMPID = A.EMPID AND X.DOCDATE = A.DOCDATE) UNION SELECT A.EMPID, B.FNAME, A.DOCDATE, A.TEMPLATE COMTEMP, A.TEMPL STEMP, A.SHIFTCNT, A.OT, A.EMPID IDCARD, CASE WHEN A.INTIME IS NOT NULL AND A.INDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.INDT || ' ' || A.INTIME, 'DD/MM/YY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END INDT1, CASE WHEN A.OUTTIME IS NOT NULL AND A.OUTDT IS NOT NULL THEN TO_CHAR(TO_TIMESTAMP(A.OUTDT || ' ' || A.OUTTIME, 'DD/MM/YY HH24:MI:SS') + NUMTODSINTERVAL(A.OT, 'MINUTE'), 'DD/MM/YYYY HH24:MI:SS') ELSE '' END OUTDT1, B.HREMPLOYMASTID, A.BRANCH FROM BHDATTA A, HREMPLOYMAST B, HREMPLOYDETAILS D, HRBANDMAST G WHERE A.EMPMAID = B.HREMPLOYMASTID AND D.BAND = G.HRBANDMASTID AND D.IDCARD = '{empId}' AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT DISTINCT A.EMPID, A.FNAME, A.DOCDATE, A.COMTEMP, A.STEMP, A.SHIFTCNT,     A.OT, A.IDCARD, A.INDT1, A.OUTDT1, A.HREMPLOYMASTID, A.BRANCH     FROM( SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.NHDATE DOCDATE, A.HOLCAT COMTEMP, A.HOLCAT STEMP, 1 SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.NHDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM HRNHDYDETAIL  A, HRNHDYBRANCHDET AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, BHDATTA F, HRBANDMAST G WHERE A.HRNHDYDETAILID = AA.HRNHDYDETAILID AND B.WORKNATURE = E.BRANCHMASTID AND D.BAND = G.HRBANDMASTID  AND AA.BRANCHNAME = E.BRANCHNAME AND B.GENDER = '{combogender.Text}' AND G.BANDID = '{comboband.Text}' AND F.EMPID = D.IDCARD AND A.NHDATE >= D.DOJ AND(A.NHDATE < D.LASTWORKDAY OR D.LASTWORKDAY IS NULL) AND F.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND (SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND A.NHDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ) A UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.ODATE DOCDATE, 'On Duty' COMTEMP, 'On Duty' STEMP, CASE WHEN A.OHDAY = 'I & II' THEN 1 ELSE 0 END SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.ODATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.ODATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM HRONDUTYDET  A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, HRBANDMAST G WHERE A.IDCARD = D.HREMPLOYDETAILSID AND B.WORKNATURE = E.BRANCHMASTID AND D.BAND = G.HRBANDMASTID AND A.OHDAY = 'I & II' AND D.IDCARD = '{empId}' AND A.ODATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, A.DOCDATE, 'EL' COMTEMP, 'EL' STEMP, A.SHIFTCNT, 0 OT, TO_NUMBER(D.IDCARD) IDCARD, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(A.DOCDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID,E.BRANCHNAME BRANCH FROM(SELECT A.IDCARD, A.IDNOCHK, A.LRDATE DOCDATE, (0 - SUM(A.STKOPBAL)) SHIFTCNT FROM HRLEAVEREGMAST A WHERE A.LRDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') GROUP BY A.IDCARD, A.IDNOCHK, A.LRDATE HAVING(0 - SUM(A.STKOPBAL)) = 1) A, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, HRBANDMAST G WHERE A.IDCARD = B.HREMPLOYMASTID AND B.WORKNATURE = E.BRANCHMASTID AND D.BAND = G.HRBANDMASTID  AND B.GENDER = '{combogender.Text}' AND G.BANDID = '{comboband.Text}' AND A.DOCDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(E.BRANCHNAME = '{combotypename.Text}' OR 'ALL' = '{combotypename.Text}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID UNION SELECT TO_NUMBER(D.IDCARD) EMPID, B.FNAME, AA.LDATE DOCDATE, 'ML' COMTEMP, 'ML' STEMP, 0 SHIFTCNT,0 OT, TO_NUMBER(D.IDCARD) IDCARD,TO_CHAR(AA.LDATE, 'DD/MM/YYYY') || ' 00:00:00' INDT1, TO_CHAR(AA.LDATE, 'DD/MM/YYYY') || ' 00:00:00' OUTDT1, B.HREMPLOYMASTID, E.BRANCHNAME BRANCH FROM HRLEAVEREQMAST A, HRLEAVEREQDETAIL  AA, HREMPLOYMAST B, HREMPLOYDETAILS D, BRANCHMAST E, HRBANDMAST G WHERE A.HRLEAVEREQMASTID = AA.HRLEAVEREQMASTID AND A.IDCARD = D.HREMPLOYDETAILSID AND D.BAND = G.HRBANDMASTID AND B.WORKNATURE = E.BRANCHMASTID AND A.LTYPE = 'ML' AND AA.LHDCNT = 1  AND D.IDCARD = '{empId}' AND AA.LDATE BETWEEN(SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND(SELECT MAX(A.ENDT) TODATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') AND B.HREMPLOYMASTID = D.HREMPLOYMASTID ) AA ) AA JOIN HREMPLOYDETAILS BB ON BB.IDCARD = AA.EMPID JOIN HREMPLOYMAST DD ON BB.HREMPLOYMASTID = DD.HREMPLOYMASTID JOIN GTLOCMAST CC ON CC.GTLOCMASTID = DD.LOCPLACE WHERE AA.EMPID = '{empId}' AND NOT EXISTS(SELECT* FROM ( SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B, GTLOCMAST C, GTDEPTDESGMAST D  WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND B.LOCPLACE = C.GTLOCMASTID  AND A.DEPTNAME = D.GTDEPTDESGMASTID AND (D.DISPNAME IN ('CANTEEN','SECURITY','DRIVER')  OR C.LOCNAME = 'HEAD OFFICE' ) UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND B.EMPTYPE = 'Trainee' UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND A.LASTWORKDAY <= (SELECT MIN(A.STDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}') UNION SELECT A.IDCARD FROM HREMPLOYDETAILS A, HREMPLOYMAST B WHERE A.HREMPLOYMASTID = B.HREMPLOYMASTID AND A.DOJ > (SELECT MAX(A.ENDT) FROMDATE FROM WEEKLYPAYFRQ A WHERE A.SNO1 = '{payPeriod}')  ) ZZ WHERE ZZ.IDCARD = AA.IDCARD ) ORDER BY 1,3";
            DataSet ds3 = Utility.ExecuteSelectQuery(query, "OTSTAMENT");
            return ds3.Tables["OTSTAMENT"];
        }

        private DataTable GetPayroll_Signature(string empId, string compcode)
        {
            string sel2 = "SELECT A.EMPNAME,A.IDCARDNO, A.signature,(SELECT AA.signature FROM ASPTBLEMP AA WHERE AA.ACTIVE='T') as msignature,to_char(c.doj,'dd-MM-YYYY') as dateofjoin,a.BYTESNAME as nameintamil,a.BYTESDESIGN as designintamil   FROM ASPTBLEMP A  JOIN GTCOMPMAST B ON A.COMPCODE=B.GTCOMPMASTID   join HREMPLOYDETAILS c on C.IDCARD=A.IDCARDNO WHERE A.IDCARDNO ='" + empId + "' and  B.COMPCODE = '" + compcode + "' ";// where  A.FINYEAR='" + combofinyear.Text + "' AND  D.compcode='" + combocompcode.Text + "'  and a.payperiod='" + allip.Items[i].SubItems[7].Text + "' AND  C.IDCARD='" + s[1].Substring(7).TrimEnd() + "' order by 1";
            DataSet ds2 = Utility.ExecuteSelectQuery(sel2, "ASPTBLEMP");
           
            return ds2.Tables["ASPTBLEMP"];
        }

        public DataTable GetPayroll_Group(string empId, string payPeriod)
        {


           string query = "SELECT XX.FINYEAR,XX.COMPCODE,XX.COMPNAME,XX.FNAME,XX.IDCARDNO,XX.BRANCH,XX.DESIGNATION,       XX.PAYPERIOD,XX.NOOFDAYS,XX.LOP,XX.EBASIC,XX.EHRA,XX.EDA,XX.ESPL,XX.ERPF,XX.ERESI,XX.EMESSFEES,XX.EOTHDED,XX.ADV,XX.SADV,       XX.BANK,XX.PAYCAT,     XX.IT,XX.EGROSS,XX.NETPAY,XX.BASIC,XX.DA,XX.HRA,XX.SPL,XX.TOTDED,XX.COMPLOGO,XX.DG,XX.PAYCAT1,NVL(YYY.TAKEN,0) TAKEN,     NVL(YYY.CLOSING,0) CLOSING,YYY.IDCARD,NVL(YYY.ELEAVE,0) ELEAVE,XX.EMPTYPE,XX.WALLO  TEST1 ,XX.EWALLO TEST2 ,XX.ETRDED TEST3  FROM (SELECT AA.FINYEAR,AA.COMPCODE,AA.COMPNAME,AA.FNAME,AA.IDCARDNO,AA.BRANCH,AA.DESIGNATION, AA.PAYPERIOD,AA.NOOFDAYS,AA.LOP,AA.EBASIC,AA.EHRA,AA.EDA,AA.ESPL,  AA.ERPF,AA.ERESI,AA.EMESSFEES,AA.EOTHDED,     AA.ADV,AA.SADV,AA.BANK,AA.PAYCAT,                AA.IT,AA.EGROSS,AA.NETPAY,AA.BASIC,AA.DA,AA.HRA,AA.SPL,AA.TOTDED,AA.COMPLOGO,  AA.DG,AA.PAYCAT1,AA.EMPTYPE ,AA.WALLO ,AA.EWALLO,AA.ETRDED  FROM ( SELECT TO_CHAR(TO_DATE(H.MPGDT,'DD/MM/YY'),'DD/MM/YYYY') AS FINYEAR,C.COMPCODE,C.COMPNAME,B.FNAME,B.IDCARDNO,  A.BRANCH,D.DESIGNATION,     A.PAYPERIOD,     A.WDAYS NOOFDAYS,A.MDAYS-A.WDAYS LOP,A.EBASIC, A.EHRA,                 A.EDA,A.ESPL,A.PF ERPF,A.ESI ERESI,  A.MESSFEES EMESSFEES,(A.EOTHDED+ROUND((CASE WHEN A.ECDED > 0 THEN  ( A.WDAYS*(450/A.MDAYS) ) ELSE 0 END),2)+A.ETDED) EOTHDED,A.LOAN ADV,A.SADV,CASE WHEN A.BANK = 'CASH' THEN ' ' ELSE A.BANK END BANK,A.PAYCAT,A.TDSN IT,A.EGROSS, ROUND(A.NETPAY-ROUND((CASE WHEN A.ECDED > 0 THEN  ( A.WDAYS*(450/A.MDAYS) ) ELSE 0 END),2)+A.ECDED+A.ETRDED,0) NETPAY  ,A.BASIC*2 BASIC,A.DA*2 DA,A.HRA*2 HRA,A.SPL*2 SPL,  A.TOTDED+ROUND((CASE WHEN A.ECDED > 0 THEN  ( A.WDAYS*(450/A.MDAYS) ) ELSE 0 END),2)-A.ECDED-A.ETRDED TOTDED  ,(SELECT LOGO FROM EDOCIMAGE1 WHERE IMGNAME='LOGO') COMPLOGO, (SELECT LOGO FROM EDOCIMAGE1      WHERE IMGNAME='DGGM') DG,TO_CHAR(TO_DATE(G.STDT,'DD/MM/YY'),'DD/MM/YYYY')||' TO '||TO_CHAR(TO_DATE(G.ENDT,'DD/MM/YY'),'DD/MM/YYYY') PAYCAT1,'{EMPTYPE}' EMPTYPE ,A.WALLO*2 WALLO   ,   A.EWALLO  ,0 ETRDED   FROM  LOPPLHPAYROLL A JOIN HREMPLOYMAST B ON B.HREMPLOYMASTID=A.EMPID JOIN GTCOMPMAST C ON C.GTCOMPMASTID=B.COMPCODE    JOIN HRDESIGNATIONMAST D ON D.HRDESIGNATIONMASTID=A.DESIGNATION JOIN HREMPLOYDETAILS E ON E.HREMPLOYMASTID=B.HREMPLOYMASTID    JOIN HRBANDMAST F ON F.HRBANDMASTID=E.BAND JOIN MONTHLYPAYFRQ G ON G.PAYPERIOD=A.PAYPERIOD JOIN HRMFRQ H ON H.PAYPERIOD=A.PAYPERIOD WHERE      H.PAYPERIOD='" + payPeriod + "' AND A.PAYPERIOD='" + payPeriod + "' AND A.PCTYPE='ACTUAL' AND B.IDCARDNO='" + empId + "' ) AA )XX,       (SELECT YY.TAKEN,YY.CLOSING,YY.IDCARD,YY.ELEAVE FROM (SELECT  DD.BRANCHNAME BRANCH,AA.IDCARD,BB.FNAME EMPNAME,BB.GENDER,EE.DISPNAME DEPT,FF.DESIGNATION,GG.BANDID ,      AA.SHIFTCNT WDAYS,AA.ELEAVE,AA.TAKEN,AA.TAKEN1,CASE WHEN (AA.ELEAVE-AA.TAKEN1) < 0  THEN 0 ELSE (AA.ELEAVE-AA.TAKEN1) END CLOSING FROM (SELECT A.IDCARD,SUM(A.SHIFTCNT) SHIFTCNT,      ROUND(SUM(A.ELEAVE),3) ELEAVE,SUM(A.TAKEN) TAKEN,SUM(A.TAKEN1) TAKEN1 FROM ( SELECT A.IDCARD,A.SHIFTCNT,0 ELEAVE,0 TAKEN,0 TAKEN1 FROM HREMPWDAY A       UNION ALL       SELECT A.EMPID IDCARD,A.SHIFTCNT,0 ELEAVE,0 TAKEN,0 TAKEN1 FROM HDATTA A,MONTHLYPAYFRQ B,HRLELIGIBLE C WHERE A.PAYPERIOD = B.PAYPERIOD AND B.PAYPERIOD1 = C.PAYPERIOD       AND A.DOCDATE <= (SELECT AA.ENDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "') AND A.SHIFTCNT > 0 UNION ALL SELECT A.EMPID IDCARD,0 SHIFTCNT,      A.SHIFTCNT*A.LEAVE ELEAVE,0 TAKEN,0 TAKEN1 FROM HDATTA A,MONTHLYPAYFRQ B,HRLELIGIBLE C WHERE A.PAYPERIOD = B.PAYPERIOD AND B.PAYPERIOD1 = C.PAYPERIOD       AND A.DOCDATE <= (SELECT AA.ENDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "') AND A.SHIFTCNT > 0       AND B.FINYR = (SELECT AA.FINYR FROM MONTHLYPAYFRQ AA    WHERE AA.PAYPERIOD='" + payPeriod + "')       UNION ALL SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,(0-SUM(A.STKOPBAL)) TAKEN,(0-SUM(A.STKOPBAL)) TAKEN1 FROM HRLEAVEREGMAST A       WHERE A.LRDATE BETWEEN ( SELECT AA.STDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD ='" + payPeriod + "' )       AND (SELECT AA.ENDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "') AND A.LTYPE <> 'ENC'       AND A.FINYEAR = (SELECT AA.FINYR FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "')         GROUP BY A.IDNOCHK UNION ALL SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,0 TAKEN,(0-SUM(A.STKOPBAL)) TAKEN1 FROM HRLEAVEREGMAST A       WHERE A.LRDATE < ( SELECT AA.STDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD ='" + payPeriod + "' )       AND A.FINYEAR = (SELECT AA.FINYR FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "')       GROUP BY A.IDNOCHK UNION ALL SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,0 TAKEN,(0-SUM(A.STKOPBAL)) TAKEN1 FROM HRLEAVEREGMAST A       WHERE A.LRDATE = ( SELECT AA.STDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD ='" + payPeriod + "') AND A.LTYPE = 'ENC'       AND ( SELECT TRIM(TO_CHAR(AA.STDT,'DD/MM')) FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD ='" + payPeriod + "') = '01/01'        AND A.FINYEAR = (SELECT AA.FINYR FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "')         GROUP BY A.IDNOCHK        UNION ALL       SELECT TO_NUMBER(BB.IDCARD) IDCARD,A.OLHDCNT SHIFTCNT,0 ELEAVE,0 TAKEN,0 TAKEN1 FROM HRONDUTYDET A,HREMPLOYDETAILS BB, MONTHLYPAYFRQ B,HRLELIGIBLE C       WHERE A.IDCARD = BB.HREMPLOYDETAILSID AND A.PAYPERIOD = B.PAYPERIOD AND B.PAYPERIOD1 = C.PAYPERIOD       AND A.ODATE  <= (SELECT AA.ENDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "')       UNION ALL       SELECT TO_NUMBER(BB.IDCARD) IDCARD,0 SHIFTCNT,A.OLHDCNT*0.05 ELEAVE,0 TAKEN,0 TAKEN1 FROM HRONDUTYDET A,HREMPLOYDETAILS BB, MONTHLYPAYFRQ B,HRLELIGIBLE C       WHERE A.IDCARD = BB.HREMPLOYDETAILSID AND A.PAYPERIOD = B.PAYPERIOD AND B.PAYPERIOD1 = C.PAYPERIOD       AND A.ODATE  <= (SELECT AA.ENDT FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "')       AND B.FINYR = (SELECT AA.FINYR FROM MONTHLYPAYFRQ AA WHERE AA.PAYPERIOD='" + payPeriod + "') ) A             GROUP BY A.IDCARD HAVING ( SUM(A.SHIFTCNT) >= 240 AND SUM(A.ELEAVE) > 0 ) ) AA,HREMPLOYMAST BB,HREMPLOYDETAILS CC,BRANCHMAST DD,GTDEPTDESGMAST EE,HRDESIGNATIONMAST FF,      HRBANDMAST GG,GTCOMPMAST HH WHERE AA.IDCARD = CC.IDCARD AND BB.HREMPLOYMASTID = CC.HREMPLOYMASTID AND BB.WORKNATURE = DD.BRANCHMASTID       AND EE.GTDEPTDESGMASTID = CC.DEPTNAME AND FF.HRDESIGNATIONMASTID = CC.DESIGNATION AND GG.HRBANDMASTID = CC.BAND AND HH.GTCOMPMASTID = BB.COMPCODE )  YY ) YYY WHERE XX.IDCARDNO=YYY.IDCARD(+) ORDER BY XX.FNAME";
            DataSet ds3 = Utility.ExecuteSelectQuery(query, "PAYROLL");
