 E ON E.HREMPLOYMASTID = B.HREMPLOYMASTID     JOIN HRBANDMAST F ON F.HRBANDMASTID = E.BAND      JOIN MONTHLYPAYFRQ G ON G.PAYPERIOD = A.PAYPERIOD      JOIN WEEKLYPAYFRQ H ON H.STDT BETWEEN G.STDT AND G.ENDT  WHERE H.SNO1 = '{payPeriod}'       AND       A.PCTYPE = 'ACTUAL' AND B.IDCARDNO = '{empId}'   ) AA ) XX,   (  SELECT YY.TAKEN,YY.CLOSING,YY.IDCARD,YY.ELEAVE FROM(    SELECT DD.BRANCHNAME BRANCH, AA.IDCARD, BB.FNAME EMPNAME, BB.GENDER, EE.DISPNAME DEPT, FF.DESIGNATION, GG.BANDID , AA.SHIFTCNT WDAYS, AA.ELEAVE, AA.TAKEN, AA.TAKEN1,     CASE WHEN (AA.ELEAVE-AA.TAKEN1) < 0  THEN 0 ELSE(AA.ELEAVE - AA.TAKEN1) END CLOSING FROM( SELECT A.IDCARD, SUM(A.SHIFTCNT) SHIFTCNT, ROUND(SUM(A.ELEAVE), 3) ELEAVE, SUM(A.TAKEN) TAKEN, SUM(A.TAKEN1) TAKEN1 FROM(SELECT A.IDCARD, A.SHIFTCNT, 0 ELEAVE, 0 TAKEN, 0 TAKEN1  FROM HREMPWDAY A UNION ALL SELECT A.EMPID IDCARD, A.SHIFTCNT, 0 ELEAVE, 0 TAKEN, 0 TAKEN1 FROM HDATTA A, WEEKLYPAYFRQ B, HRLELIGIBLE C  WHERE A.DOCDATE BETWEEN B.STDT AND B.ENDT AND A.DOCDATE <= (SELECT AA.ENDT FROM WEEKLYPAYFRQ AA  WHERE AA.SNO1 = '{payPeriod}') AND A.SHIFTCNT > 0 UNION ALL SELECT A.EMPID IDCARD, 0 SHIFTCNT, A.SHIFTCNT * A.LEAVE ELEAVE, 0 TAKEN, 0 TAKEN1  FROM HDATTA A, WEEKLYPAYFRQ B, HRLELIGIBLE C WHERE A.DOCDATE BETWEEN B.STDT AND B.ENDT AND A.DOCDATE <= ( SELECT AA.ENDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') AND A.SHIFTCNT > 0 AND B.FINYR = (SELECT AA.FINYR FROM WEEKLYPAYFRQ AA   WHERE AA.SNO1 = '{payPeriod}') UNION ALL SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,(0 - SUM(A.STKOPBAL)) TAKEN,(0 - SUM(A.STKOPBAL)) TAKEN1 FROM HRLEAVEREGMAST A WHERE A.LRDATE BETWEEN(SELECT AA.STDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') AND( SELECT AA.ENDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') AND A.LTYPE <> 'ENC' AND A.FINYEAR = (SELECT AA.FINYR FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') GROUP BY A.IDNOCHK UNION ALL SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,0 TAKEN,(0 - SUM(A.STKOPBAL)) TAKEN1  FROM HRLEAVEREGMAST A WHERE A.LRDATE < (SELECT AA.STDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}' ) AND A.FINYEAR = (  SELECT AA.FINYR FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') GROUP BY A.IDNOCHK  UNION ALL   SELECT TO_NUMBER(A.IDNOCHK) IDCARD,0 SHIFTCNT,0 ELEAVE,0 TAKEN,(0 - SUM(A.STKOPBAL)) TAKEN1 FROM HRLEAVEREGMAST A WHERE A.LRDATE = ( SELECT AA.STDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}' ) AND A.LTYPE = 'ENC' AND(SELECT TRIM(TO_CHAR(AA.STDT, 'DD/MM')) FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') = '01/01'  AND A.FINYEAR = (SELECT AA.FINYR FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') GROUP BY A.IDNOCHK UNION ALL SELECT TO_NUMBER(BB.IDCARD) IDCARD,A.OLHDCNT SHIFTCNT,0 ELEAVE,0 TAKEN,0 TAKEN1   FROM HRONDUTYDET A, HREMPLOYDETAILS BB, WEEKLYPAYFRQ B, HRLELIGIBLE C WHERE A.IDCARD = BB.HREMPLOYDETAILSID AND A.ODATE BETWEEN B.STDT AND B.ENDT  AND A.ODATE <= (SELECT AA.ENDT FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}')  UNION ALL   SELECT TO_NUMBER(BB.IDCARD) IDCARD,0 SHIFTCNT,A.OLHDCNT * 0.05 ELEAVE,0 TAKEN,0 TAKEN1 FROM HRONDUTYDET A, HREMPLOYDETAILS BB, WEEKLYPAYFRQ B, HRLELIGIBLE C  WHERE A.IDCARD = BB.HREMPLOYDETAILSID  AND A.ODATE BETWEEN B.STDT AND B.ENDT AND A.ODATE <= (SELECT AA.ENDT FROM WEEKLYPAYFRQ AA      WHERE AA.SNO1 = '{payPeriod}') AND B.FINYR = (SELECT AA.FINYR FROM WEEKLYPAYFRQ AA WHERE AA.SNO1 = '{payPeriod}') ) A  GROUP BY A.IDCARD HAVING(SUM(A.SHIFTCNT) >= 240 AND SUM(A.ELEAVE) > 0 ) ) AA,HREMPLOYMAST BB, HREMPLOYDETAILS CC,BRANCHMAST DD, GTDEPTDESGMAST EE,HRDESIGNATIONMAST FF, HRBANDMAST GG,GTCOMPMAST HH WHERE AA.IDCARD = CC.IDCARD AND BB.HREMPLOYMASTID = CC.HREMPLOYMASTID AND BB.WORKNATURE = DD.BRANCHMASTID AND EE.GTDEPTDESGMASTID = CC.DEPTNAME AND FF.HRDESIGNATIONMASTID = CC.DESIGNATION AND GG.HRBANDMASTID = CC.BAND AND HH.GTCOMPMASTID = BB.COMPCODE )  YY    ) YYY      WHERE XX.IDCARDNO = YYY.IDCARD(+) ORDER BY XX.FNAME";        
         
            DataSet ds4 = Utility.ExecuteSelectQuery(query, "PAYROLL");
