        public void Prints()
    {
            if (printDialog1.ShowDialog() == DialogResult.OK)//,b.intime,b.intime1, b.outtime,b.outtime1,c.address,c.pincode 
            {
                if (dtprint1.Rows.Count == 0)
                {
                    MessageBox.Show("No data found.");
                    return;
                }

                string folderLocation = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.Desktop),
                    "PaySlip-Download"
                );

                if (!Directory.Exists(folderLocation))
                {
                    Directory.CreateDirectory(folderLocation);
                }

                // Safe file name
                string empName = dtprint1.Rows[0]["FNAME"].ToString();
                string payPeriod = dtprint1.Rows[0]["PAYPERIOD"].ToString();

                string safeName = string.Join("_", empName.Split(Path.GetInvalidFileNameChars()));

                string filePath = Path.Combine(folderLocation,
                    $"{safeName}_{payPeriod}_PaySlip.pdf");

                using (var reportdocument = new CrystalDecisions.CrystalReports.Engine.ReportDocument())
                {
                    reportdocument.Load(Path.Combine(Application.StartupPath, "Report\\Lovely\\OTReport.rpt"));

                    // ✔ Correct mapping (verify with your report)
                    reportdocument.Database.Tables["DataTable1"].SetDataSource(dtprint1);
                    reportdocument.Database.Tables["DataTable2"].SetDataSource(dtprint2);
                    reportdocument.Database.Tables["DataTable3"].SetDataSource(dtprint3);
                    reportdocument.Database.Tables["DataTable4"].SetDataSource(dtprint4);
                    // ✔ Export PDF
                    reportdocument.ExportToDisk(ExportFormatType.PortableDocFormat, filePath);

                    // ✔ Print
                    reportdocument.PrintOptions.PrinterName = printDialog1.PrinterSettings.PrinterName;
                    reportdocument.PrintToPrinter(
                        printDialog1.PrinterSettings.Copies,
                        printDialog1.PrinterSettings.Collate,
                        printDialog1.PrinterSettings.FromPage,
                        printDialog1.PrinterSettings.ToPage
                    );

                    reportdocument.Close();
                }
                               datasave();empty();
                dtprint1 = null;
                dtprint2 = null; dtprint3 = null;

            }

        }

